"""Generate derived package files from the authored JSON.

* ``assessment.csv`` and ``preliminary-observations.csv`` - flat views for
  spreadsheets and action-register preparation.
* ``open-questions.md`` - prioritised, evidence-linked questions.
* ``discovery-coverage.json`` - coverage per domain, reported separately from
  maturity. Maturity is shown as a distribution (plus mean of *scored*
  criteria only); unknown and not-applicable are disclosed, never folded into a
  number, and no overall application score is produced.
"""

from __future__ import annotations

import csv
import io
from collections import Counter
from pathlib import Path
from typing import Any

from . import SCHEMA_VERSION
from .paths import DOMAIN_TITLES, JSON_FILES
from .util import dump_json, load_json, utc_now, write_text

SCORING_METHOD = (
    "Per domain: count of criteria by maturity level (0-5), unknown (U) and not applicable (N/A). "
    "mean_of_scored averages numeric levels only and excludes U and N/A. Coverage counts are independent of maturity. "
    "No overall application score is calculated."
)

ASSESSMENT_COLUMNS = [
    "id", "domain", "domain_title", "title", "source_profile", "emphasis", "applicability", "status", "maturity",
    "confidence", "discovery_coverage", "assurance_level", "risk_severity", "current_implementation",
    "strengths", "potential_gaps", "unknowns", "conflicting_evidence", "evidence_refs", "validation_evidence_refs",
    "discovery_attempts", "follow_up_questions", "expected_baseline", "baseline_verified_policy",
]

OBSERVATION_COLUMNS = [
    ("id", "Observation ID"), ("domain", "Domain"), ("observation", "Observation"),
    ("existing_implementation", "Existing implementation"), ("nature", "Strength or potential gap"),
    ("category", "Category"), ("implication", "Implication"), ("evidence_refs", "Evidence references"),
    ("criteria", "Criteria"), ("confidence", "Confidence"), ("risk_severity", "Preliminary risk severity"),
    ("improvement_options", "Potential improvement opportunity"), ("follow_up_question", "Follow-up question"),
    ("proposed_action", "Proposed action"), ("owner", "Owner"), ("target_date", "Target date"),
    ("validation_status", "Validation status"),
]


def _cell(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, list):
        parts = []
        for v in value:
            if isinstance(v, dict) and "option" in v:
                parts.append(f"{v['option']} (trade-offs: {v.get('trade_offs', '')})")
            else:
                parts.append(str(v))
        return "; ".join(parts)
    return str(value)


def _csv(rows: list[list[str]]) -> str:
    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\n")
    writer.writerows(rows)
    return buf.getvalue()


def assessment_csv(assessment: dict[str, Any]) -> str:
    rows = [ASSESSMENT_COLUMNS]
    for c in assessment.get("criteria", []):
        baseline = c.get("expected_baseline") or {}
        values = {**c, "domain_title": DOMAIN_TITLES.get(c["domain"], ""),
                  "expected_baseline": baseline.get("statement"), "baseline_verified_policy": baseline.get("verified_policy")}
        rows.append([_cell(values.get(col)) for col in ASSESSMENT_COLUMNS])
    return _csv(rows)


def observations_csv(assessment: dict[str, Any]) -> str:
    rows = [[label for _, label in OBSERVATION_COLUMNS]]
    for o in assessment.get("observations", []):
        rows.append([_cell(o.get(key)) for key, _ in OBSERVATION_COLUMNS])
    return _csv(rows)


AUDIENCE_LABEL = {
    "development_team": "Development team", "business_owner": "Business owner", "platform_owner": "Platform owner",
    "security_owner": "Security owner", "operations_owner": "Operations owner", "data_owner": "Data owner",
}
PRIORITY_LABEL = {
    "P1": "P1 - could materially change architectural recommendations",
    "P2": "P2 - needed to confirm preliminary observations",
    "P3": "P3 - completes the picture",
}


def open_questions_md(assessment: dict[str, Any]) -> str:
    criteria = {c["id"]: c for c in assessment.get("criteria", [])}
    questions = sorted(assessment.get("open_questions", []), key=lambda q: (q["priority"], q["audience"], q["id"]))
    lines = [
        "# Open questions",
        "",
        "Evidence-driven questions for the development team, business owner and platform owner, ordered by their "
        "potential influence on architectural recommendations. Generated by `ada.py render` from `assessment.json`.",
        "",
    ]
    if not questions:
        lines += ["No open questions were recorded.", ""]
    for priority in ("P1", "P2", "P3"):
        group = [q for q in questions if q["priority"] == priority]
        if not group:
            continue
        lines += [f"## {PRIORITY_LABEL[priority]}", ""]
        for q in group:
            lines.append(f"### {q['id']} ({AUDIENCE_LABEL.get(q['audience'], q['audience'])})")
            lines.append("")
            lines.append(q["question"])
            lines.append("")
            lines.append(f"- **Why it matters:** {q['why_it_matters']}")
            if q.get("criteria"):
                refs = ", ".join(f"{cid} ({criteria[cid]['title']})" if cid in criteria else cid for cid in q["criteria"])
                lines.append(f"- **Criteria:** {refs}")
            if q.get("evidence_refs"):
                lines.append(f"- **Evidence:** {', '.join(q['evidence_refs'])}")
            lines.append("")

    unresolved = [c for c in assessment.get("criteria", []) if c.get("maturity") == "U" and c.get("emphasis") in ("high", "critical")]
    if unresolved:
        lines += ["## Unresolved high-emphasis criteria", "",
                  "Criteria with elevated emphasis that remain unknown. Each should be covered by a question above or by a follow-up question below.", "",
                  "| Criterion | Emphasis | Follow-up |", "| --- | --- | --- |"]
        for c in unresolved:
            follow = "; ".join(c.get("follow_up_questions") or []) or "-"
            lines.append(f"| {c['id']} {c['title']} | {c['emphasis']} | {follow.replace('|', '/')} |")
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def coverage(assessment: dict[str, Any], evidence: dict[str, Any]) -> dict[str, Any]:
    criteria = assessment.get("criteria", [])
    ev_by_criterion: Counter[str] = Counter()
    for ev in evidence.get("evidence", []):
        for cid in set(ev.get("criteria", [])):
            ev_by_criterion[cid] += 1
    domains = []
    total_status: Counter[str] = Counter()
    total_coverage: Counter[str] = Counter()
    total_maturity: Counter[str] = Counter()
    for dom in sorted({c["domain"] for c in criteria} | set(DOMAIN_TITLES)):
        items = [c for c in criteria if c["domain"] == dom]
        status = Counter(c["status"] for c in items)
        cov = Counter(c["discovery_coverage"] for c in items)
        mat = Counter(c["maturity"] for c in items)
        scored = [int(m) for m in (c["maturity"] for c in items) if m.isdigit()]
        total_status.update(status)
        total_coverage.update(cov)
        total_maturity.update(mat)
        domains.append({
            "domain": dom,
            "title": DOMAIN_TITLES.get(dom, dom),
            "criteria_total": len(items),
            "not_applicable": sum(1 for c in items if c["applicability"] == "not_applicable"),
            "status_counts": dict(sorted(status.items())),
            "coverage_counts": dict(sorted(cov.items())),
            "evidence_records": sum(ev_by_criterion[c["id"]] for c in items),
            "maturity": {
                "scored": len(scored),
                "unknown": mat.get("U", 0),
                "excluded_not_applicable": mat.get("N/A", 0),
                "distribution": {lvl: mat.get(lvl, 0) for lvl in ("0", "1", "2", "3", "4", "5", "U", "N/A")},
                "mean_of_scored": round(sum(scored) / len(scored), 2) if scored else None,
            },
        })
    investigated = sum(1 for d in domains if d["criteria_total"] and d["coverage_counts"].get("not_investigated", 0) < d["criteria_total"])
    return {
        "schema_version": SCHEMA_VERSION,
        "generated_at": utc_now(),
        "profiles": list(assessment.get("profiles", [])),
        "scoring_method": SCORING_METHOD,
        "domains": domains,
        "totals": {
            "criteria": len(criteria),
            "domains_with_criteria": sum(1 for d in domains if d["criteria_total"]),
            "domains_investigated": investigated,
            "evidence_records": len(evidence.get("evidence", [])),
            "observations": len(assessment.get("observations", [])),
            "open_questions": len(assessment.get("open_questions", [])),
            "status_counts": dict(sorted(total_status.items())),
            "coverage_counts": dict(sorted(total_coverage.items())),
            "maturity_distribution": {lvl: total_maturity.get(lvl, 0) for lvl in ("0", "1", "2", "3", "4", "5", "U", "N/A")},
        },
    }


def render(out: Path) -> list[str]:
    out = Path(out)
    for name in JSON_FILES:
        path = out / name
        if path.exists():
            dump_json(path, load_json(path))
    assessment = load_json(out / "assessment.json")
    evidence = load_json(out / "evidence.json")
    write_text(out / "assessment.csv", assessment_csv(assessment))
    write_text(out / "preliminary-observations.csv", observations_csv(assessment))
    write_text(out / "open-questions.md", open_questions_md(assessment))
    dump_json(out / "discovery-coverage.json", coverage(assessment, evidence))
    return ["assessment.csv", "preliminary-observations.csv", "open-questions.md", "discovery-coverage.json"]
